impl Solution {
    pub fn min_moves(target: i32, max_doubles: i32) -> i32 {
        let mut target = target;
        let mut max_doubles = max_doubles;
        let mut moves = 0;

        while target > 1 {
            if max_doubles > 0 && target % 2 == 0 {
                target /= 2;
                max_doubles -= 1;
            } else {
                moves += 1;
                target -= 1;
            }
        }

        moves + max_doubles
    }
}

